import sys;sys.path.insert(0,'.')
from common4 import *
SN=E('English','እንግሊዝኛ')
def sq(sent,opts,a=0): return {'say':sent.replace('___',opts[a]),'sayLang':'en-US','q':sent,'o':opts,'a':a}
def eq(en,am,opts,a=0,say=None):
    d={'q':E(en,am) if am else en,'o':[o if isinstance(o,str) else E(*o) for o in opts],'a':a}
    if say: d['say']=say;d['sayLang']='en-US'
    return d
def read(title,tip,ptitle,paras,items):
    return {'title':E(*title),'type':'quiz','tip':E(*tip),'passage':{'title':ptitle,'paras':paras,'say':' '.join(paras),'sayLang':'en-US'},'items':items}
def U(n,title,data,extra,exam,nt,summ):
    unit(f'g4-english-{n}','english',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on English for Ethiopia, Grade 4, Unit {n}: {title[0]}.',f'በEnglish for Ethiopia 4ኛ ክፍል፣ ክፍል {n} ({title[1]}) ላይ የተመሰረተ።'),'K1.engMissions',data,extra,exam,nt,summ)
